"""Icônes FONCTIONNELLES (par catégorie d'usage) pour les applications existantes : navigateur, lecteur PDF, éditeur de code…
Pas de logos de marque : une application connue reçoit l'icône de son rôle (voir known_apps.py) — cohérence visuelle garantie."""
from icon_lib import *
def tc(name, i=1): return TILES[name][i]
def pane(c0='#FFFFFF', c1='#EEF2FF', x=10, y=11, w=44, h=42, r=7): return sh(G(rr(x, y, w, h, r), c0, c1))
def F(id, name, cat, bg, el, alias=()): icon(id, name, cat, bg, el, alias)
def L(pts, c, w=2.6, a=.8): return line(pts, c, w, a)
